import { Download, FileText, GitBranch, ListPlus, MessageSquare, Plus, Upload } from 'lucide-react'
import type { AiAssistantRecord, AiSessionRecord, AiTopicRecord } from '@shared/ai-types'
import { EmptyState, StatusBadge } from '../../components/ui/Feedback'
import { IconButton } from '../../components/ui/Button'

export function CherrySessionSidebar({ sessions, activeId, query, onQueryChange, onSelect, onCreate, onDelete, onRename, onBranch, onExport, onImport, assistants = [], topics = [], activeAssistantId = '', onAssistantChange, onTopicCreate, onTopicSelect }: { sessions: AiSessionRecord[]; activeId: string | null; query: string; onQueryChange: (value: string) => void; onSelect: (id: string) => void; onCreate: () => void; onDelete: (id: string) => void; onRename: (id: string, title: string) => Promise<void>; onBranch: () => void; onExport: (format: 'json' | 'md') => void; onImport: () => void; assistants?: AiAssistantRecord[]; topics?: AiTopicRecord[]; activeAssistantId?: string; onAssistantChange?: (id: string) => void; onTopicCreate?: () => void; onTopicSelect?: (id: string) => void }) {
  const groups = sessions.reduce<Record<string, AiSessionRecord[]>>((result, session) => {
    const date = new Date(session.updated_at)
    const today = new Date()
    const startToday = new Date(today.getFullYear(), today.getMonth(), today.getDate()).getTime()
    const sessionTime = Number.isNaN(date.getTime()) ? 0 : date.getTime()
    const key = sessionTime >= startToday ? '今天' : sessionTime >= startToday - 86400000 ? '昨天' : sessionTime >= startToday - 7 * 86400000 ? '本周' : '更早'
    ;(result[key] ||= []).push(session)
    return result
  }, {})
  const rename = async (session: AiSessionRecord) => {
    const next = window.prompt('重命名会话', session.title || '未命名会话')
    if (next && next.trim() && next.trim() !== session.title) await onRename(session.id, next.trim())
  }
  return <div className="space-y-3">
    <div className="flex items-center justify-between gap-2"><div><div className="text-xs font-semibold text-[var(--color-text-primary)]">会话</div><div className="mt-0.5 text-[10px] text-[var(--color-text-secondary)]">统一 Agent 历史</div></div><div className="flex items-center gap-1"><IconButton icon={Plus} label="新建会话" onClick={onCreate} /><IconButton icon={GitBranch} label="复制当前会话分支" onClick={onBranch} disabled={!activeId} /><IconButton icon={Download} label="导出当前会话 JSON" onClick={() => onExport('json')} disabled={!activeId} /><IconButton icon={FileText} label="导出当前会话 Markdown" onClick={() => onExport('md')} disabled={!activeId} /></div></div>
    {assistants.length > 0 && <label className="block space-y-1"><span className="px-1 text-[10px] font-semibold text-[var(--color-text-secondary)]">助手</span><select className="ui-field w-full text-xs" value={activeAssistantId} onChange={event => onAssistantChange?.(event.target.value)} aria-label="选择助手"><option value="">默认助手</option>{assistants.map(assistant => <option key={assistant.id} value={assistant.id}>{assistant.name}</option>)}</select></label>}
    {activeId && <section className="rounded-lg border border-[var(--color-border)] bg-[var(--color-bg-secondary)] p-2"><div className="flex items-center justify-between gap-2"><span className="text-[10px] font-semibold text-[var(--color-text-secondary)]">主题</span><button type="button" className="ui-toolbar-button h-6 px-1.5" onClick={onTopicCreate} aria-label="新建主题" title="新建主题"><ListPlus size={13} /></button></div>{topics.length === 0 ? <div className="mt-1 text-[10px] text-[var(--color-text-secondary)]">暂无主题</div> : <div className="mt-1 space-y-1">{topics.map(topic => <button type="button" key={topic.id} onClick={() => onTopicSelect?.(topic.id)} className="block w-full truncate rounded px-1.5 py-1 text-left text-[10px] text-[var(--color-text-secondary)] hover:bg-[var(--color-bg-tertiary)] hover:text-[var(--color-text-primary)]">{topic.pinned ? '★ ' : ''}{topic.title || '未命名主题'}</button>)}</div>}</section>}
    <div className="flex gap-1"><input className="ui-field min-w-0 flex-1 text-xs" value={query} onChange={event => onQueryChange(event.target.value)} placeholder="搜索会话、模型或 Runtime" aria-label="搜索会话" /><button type="button" className="ui-toolbar-button" onClick={onImport} aria-label="导入 Agent 会话" title="导入 JSON 会话"><Upload size={14} /></button></div>
    {sessions.length === 0 ? <EmptyState icon={MessageSquare} title="暂无会话" description="创建一个 Agent 会话" /> : Object.entries(groups).map(([group, items]) => <section key={group} className="space-y-1.5"><div className="px-1 text-[10px] font-semibold uppercase tracking-wide text-[var(--color-text-secondary)]">{group}</div>{items.map(session => <div key={session.id} className={'group w-full rounded-xl border p-2.5 transition-colors ' + (activeId === session.id ? 'border-[var(--color-accent)] bg-[var(--color-accent)]/10' : 'border-[var(--color-border)] hover:border-[var(--color-border-strong)]')}><button type="button" onClick={() => onSelect(session.id)} className="w-full text-left"><div className="truncate text-xs font-medium text-[var(--color-text-primary)]">{session.title || '未命名会话'}</div><div className="mt-1 flex items-center justify-between gap-2 text-[10px] text-[var(--color-text-secondary)]"><span className="min-w-0 truncate">{session.runtime} · {session.model_id || '未选择模型'}</span><StatusBadge tone={session.status === 'failed' ? 'danger' : session.status === 'running' ? 'warning' : 'success'}>{session.status}</StatusBadge></div></button><div className="mt-1 flex justify-end gap-2 opacity-0 transition-opacity group-hover:opacity-100 focus-within:opacity-100"><button type="button" className="text-[10px] text-[var(--color-text-secondary)] hover:text-[var(--color-text-primary)]" onClick={() => void rename(session)}>重命名</button><button type="button" className="text-[10px] text-red-500" onClick={() => onDelete(session.id)}>删除</button></div></div>)}</section>)}
  </div>
}
